// 第143-202行：validateField 函数
const validateField = (fieldId) => {
  const fieldConfig = formConfig.value.formInfo.find((f) => f.id === fieldId)
  const value = formData[fieldId]

  // 优先使用新版本 rules 数组
  if (fieldConfig.rules && Array.isArray(fieldConfig.rules)) {
    const result = validate(null, value, fieldConfig)
    if (!result.valid) {
      errors[fieldId] = result.message
      return false
    }
  }

  // 兼容旧版本 role 配置
  const validateType = fieldConfig.role?.type
  const result = validate(validateType, value, fieldConfig)
  // ...
}
```

